"""Checkers (Draughts) - two-player console game.

Run: python main.py
Notation: from-to squares, e.g. b2-c3 (multi-jumps one hop at a time).
"""

import re


def parse_sq(s):
    s = s.strip().lower()
    if len(s) == 2 and s[0] in "abcdefgh" and s[1] in "12345678":
        return (8 - int(s[1]), ord(s[0]) - 97)
    return None


def sq_name(r, c):
    return chr(97 + c) + str(8 - r)


def inb(r, c):
    return 0 <= r < 8 and 0 <= c < 8


def dirs_for(p):
    if p.isupper():
        return ((-1, -1), (-1, 1), (1, -1), (1, 1))
    return ((-1, -1), (-1, 1)) if p == "r" else ((1, -1), (1, 1))


def caps_from(board, r, c):
    p = board[r][c]
    out = []
    for dr, dc in dirs_for(p):
        mr, mc, lr, lc = r + dr, c + dc, r + 2 * dr, c + 2 * dc
        if inb(lr, lc) and board[lr][lc] == ".":
            m = board[mr][mc]
            if m != "." and m.lower() != p.lower():
                out.append((lr, lc))
    return out


def steps_from(board, r, c):
    p = board[r][c]
    return [
        (r + dr, c + dc)
        for dr, dc in dirs_for(p)
        if inb(r + dr, c + dc) and board[r + dr][c + dc] == "."
    ]


def moves_for(board, pl):
    caps = {}
    for r in range(8):
        for c in range(8):
            if board[r][c] != "." and board[r][c].lower() == pl and caps_from(board, r, c):
                caps[(r, c)] = caps_from(board, r, c)
    if caps:
        return caps, True
    steps = {}
    for r in range(8):
        for c in range(8):
            if board[r][c] != "." and board[r][c].lower() == pl and steps_from(board, r, c):
                steps[(r, c)] = steps_from(board, r, c)
    return steps, False


class Game:
    def __init__(self):
        self.board = [["." for _ in range(8)] for _ in range(8)]
        for r in range(3):
            for c in range(8):
                if (r + c) % 2:
                    self.board[r][c] = "b"
        for r in range(5, 8):
