        side = "Red" if self.turn == "r" else "Black"
        print("Turn: %s%s" % (side, " (must continue jumping)" if self.cont else ""))

    def apply(self, fr, fc, tr, tc):
        p = self.board[fr][fc]
        cap = None
        if abs(tr - fr) == 2:
            cap = ((fr + tr) // 2, (fc + tc) // 2)
            self.board[cap[0]][cap[1]] = "."
        self.board[tr][tc] = p
        self.board[fr][fc] = "."
        promoted = False
        if p == "r" and tr == 0:
            self.board[tr][tc] = "R"
            promoted = True
        elif p == "b" and tr == 7:
            self.board[tr][tc] = "B"
